"use strict";
module.exports = "<section class=\"booking-page\">\n  <div class=\"container booking-shell\">\n    <div class=\"section-head\">\n      <span class=\"eyebrow\">{{ t('adminEyebrow') }}</span>\n      <h1>{{ t('adminTitle') }}</h1>\n      <p>{{ t('adminIntro') }}</p>\n    </div>\n\n    <div class=\"booking-tabs\" *ngIf=\"!loading && bookings.length > 0\">\n      <button type=\"button\" [class.active]=\"activeDateTab === 'upcoming'\" (click)=\"setDateTab('upcoming')\">{{ t('auto.home.bookings.bookings.component.upcoming') }}<span>{{ upcomingBookingsCount }}</span>\n      </button>\n      <button type=\"button\" [class.active]=\"activeDateTab === 'past'\" (click)=\"setDateTab('past')\">{{ t('auto.home.bookings.bookings.component.past') }}<span>{{ pastBookingsCount }}</span>\n      </button>\n    </div>\n\n    <div class=\"booking-toolbar booking-toolbar-grid\">\n      <label class=\"search-box\">\n        <span>{{ t('search') }}</span>\n        <input\n          type=\"search\"\n          name=\"bookingSearch\"\n          [(ngModel)]=\"searchTerm\"\n          [placeholder]=\"t('searchPlaceholder')\"\n          autocomplete=\"off\"\n        />\n      </label>\n\n      <label>\n        <span>{{ t('status') }}</span>\n        <select [(ngModel)]=\"statusFilter\">\n          <option [value]=\"'all'\">{{ t('allStatuses') }}</option>\n          <option [value]=\"'not_confirmed'\">{{ t('notConfirmed') }}</option>\n          <option [value]=\"'confirmed'\">{{ t('confirmed') }}</option>\n          <option [value]=\"'payment_done'\">{{ t('paymentDone') }}</option>\n        </select>\n      </label>\n\n      <label>\n        <span>{{ t('warranty') }}</span>\n        <select [(ngModel)]=\"warrantyFilter\">\n          <option [value]=\"'all'\">{{ t('allWarranties') }}</option>\n          <option [value]=\"'not_selected'\">{{ t('notSelected') }}</option>\n          <option [value]=\"'cash'\">{{ t('cashSelected') }}</option>\n          <option [value]=\"'card_selected'\">{{ t('cardSelected') }}</option>\n          <option [value]=\"'card_registered'\">{{ t('cardRegistered') }}</option>\n        </select>\n      </label>\n\n      <label>\n        <span>{{ t('auto.home.bookings.bookings.component.platform') }}</span>\n        <select [(ngModel)]=\"platformFilter\">\n          <option [value]=\"'all'\">{{ t('auto.home.bookings.bookings.component.all_platforms') }}</option>\n          <option [value]=\"'direct'\">{{ t('auto.home.bookings.bookings.component.direct_alegria') }}</option>\n          <option [value]=\"'clickandboat'\">{{ t('auto.home.bookings.bookings.component.click_boat') }}</option>\n          <option [value]=\"'samboat'\">{{ t('auto.home.bookings.bookings.component.samboat') }}</option>\n          <option [value]=\"'other'\">{{ t('auto.home.bookings.bookings.component.other') }}</option>\n        </select>\n      </label>\n\n      <label>\n        <span>{{ t('orderBy') }}</span>\n        <select [(ngModel)]=\"sortField\">\n          <option [value]=\"'date'\">{{ t('date') }}</option>\n          <option [value]=\"'customer'\">{{ t('customer') }}</option>\n          <option [value]=\"'status'\">{{ t('auto.home.bookings.bookings.component.status') }}</option>\n          <option [value]=\"'total'\">{{ t('totalPrice') }}</option>\n          <option [value]=\"'balance'\">{{ t('remaining90') }}</option>\n        </select>\n      </label>\n\n      <label>\n        <span>{{ t('direction') }}</span>\n        <select [(ngModel)]=\"sortDirection\">\n          <option [value]=\"'asc'\">{{ t('ascending') }}</option>\n          <option [value]=\"'desc'\">{{ t('descending') }}</option>\n        </select>\n      </label>\n\n      <button class=\"btn btn-secondary\" type=\"button\" (click)=\"resetFilters()\">{{ t('resetFilters') }}</button>\n      <a class=\"btn btn-secondary\" routerLink=\"/admin/offers\">{{ t('offers') }}</a>\n      <button class=\"btn btn-primary\" type=\"button\" (click)=\"openCreateReservation()\">{{ t('auto.home.bookings.bookings.component.new_reservation') }}</button>\n      <button class=\"btn btn-secondary\" type=\"button\" (click)=\"loadBookings()\">{{ t('refresh') }}</button>\n    </div>\n\n    <section id=\"create-reservation-panel\" class=\"create-reservation-panel\" *ngIf=\"showCreateReservation\">\n      <div class=\"create-panel-header\">\n        <div>\n          <span class=\"eyebrow\">{{ t('auto.home.bookings.bookings.component.reservation_cockpit') }}</span>\n          <h2>{{ t('auto.home.bookings.bookings.component.new_reservation_bb6c90') }}</h2>\n          <p>{{ t('auto.home.bookings.bookings.component.create_a_direct_click_boat_samboat_or_other_platfo') }}</p>\n        </div>\n        <div class=\"create-panel-actions\">\n          <a class=\"btn btn-primary\" routerLink=\"/my-external-bookings\">{{ t('auto.home.bookings.bookings.component.open_reservation_form') }}</a>\n          <button class=\"btn btn-secondary\" type=\"button\" (click)=\"closeCreateReservation()\">{{ t('auto.home.bookings.bookings.component.close') }}</button>\n        </div>\n      </div>\n\n      <div class=\"embedded-reservation-form\">\n        <app-admin-external-bookings\n          [embedded]=\"true\"\n          (bookingCreated)=\"onReservationCreated($event)\"\n        ></app-admin-external-bookings>\n      </div>\n\n      <p class=\"create-panel-help\">{{ t('auto.home.bookings.bookings.component.if_the_embedded_form_is_not_visible_on_your_browse') }}<strong>{{ t('auto.home.bookings.bookings.component.open_reservation_form') }}</strong>.\n      </p>\n    </section>\n\n    <p class=\"success-message\" *ngIf=\"createReservationMessage\">{{ createReservationMessage }}</p>\n\n    <p *ngIf=\"loading\" class=\"muted\">{{ t('loadingBookings') }}</p>\n    <p *ngIf=\"!loading && errorMessage\" class=\"error-message\">{{ errorMessage }}</p>\n    <p *ngIf=\"!loading && !errorMessage && bookings.length === 0\" class=\"muted\">\n      {{ t('noBookingsFirebase') }} <strong>{{ t('auto.home.bookings.bookings.component.bnbookings') }}</strong>.\n    </p>\n\n    <div class=\"list-summary\" *ngIf=\"!loading && bookings.length > 0\">\n      {{ t('showingBookings') }} <strong>{{ activeTabBookingsCount }}</strong> {{ activeDateTab === 'upcoming' ? t('upcoming') : t('past') }} {{ t('bookingsOutOf') }} <strong>{{ bookings.length }}</strong> {{ t('total') }}\n    </div>\n\n    <div class=\"bookings-list\" *ngIf=\"!loading && filteredBookings.length > 0\">\n      <button\n        class=\"booking-list-row\"\n        type=\"button\"\n        *ngFor=\"let booking of filteredBookings; trackBy: trackByBookingId\"\n        (click)=\"openBooking(booking)\"\n      >\n        <button class=\"status-pill status-clickable\" type=\"button\" (click)=\"openStatusModal(booking, $event)\">{{ getStatusLabel(booking) }}</button>\n\n        <span class=\"booking-main\">\n          <strong>{{ booking.customerName || t('customerNotSet') }}</strong>\n          <small>{{ booking.email || t('noEmail') }}</small>\n        </span>\n\n        <span class=\"booking-trip\">\n          <strong>{{ booking.outingType || t('outing') }}</strong>\n          <small>\n            {{ booking.outingDate || t('dateNotSet') }}\n            <ng-container *ngIf=\"booking.departureTime\">• {{ booking.departureTime }}</ng-container>\n          </small>\n        </span>\n\n        <span class=\"booking-platform\">\n          <strong>{{ getPlatformLabel(booking) }}</strong>\n          <small>{{ getPlatformReference(booking) || 'Platform' }}</small>\n        </span>\n\n        <span class=\"booking-price\">\n          <strong>€{{ booking.totalPrice || 0 }}</strong>\n          <small>{{ t('totalPrice') }}</small>\n        </span>\n\n        <span class=\"row-actions\" (click)=\"$event.stopPropagation()\">\n          <!-- Admin cannot pay deposit or remaining balance. Open the detail page for warranty actions. -->\n          <span class=\"row-chevron\">›</span>\n        </span>\n      </button>\n    </div>\n\n    <p *ngIf=\"!loading && bookings.length > 0 && filteredBookings.length === 0\" class=\"muted\">\n      {{ t('noBookingMatch') }}\n    </p>\n    <div class=\"balance-modal-backdrop\" *ngIf=\"false\">\n      <div class=\"balance-modal\">\n        <h2>{{ t('recordRemainingPayment') }}</h2>\n        <p>\n          <strong>{{ selectedBalanceBooking.customerName }}</strong><br />\n          Total: €{{ selectedBalanceBooking.totalPrice || 0 }}<br />\n          Deposit 10%: €{{ getDepositAmount(selectedBalanceBooking) }} · {{ isDepositPaid(selectedBalanceBooking) ? t('depositPaid') : t('depositPending') }}<br />\n          Warranty mode: {{ getWarrantyModeLabel(selectedBalanceBooking) }}<br />\n          {{ t('stripeWarrantyCard') }}: {{ getWarrantyCardLabel(selectedBalanceBooking) }}<br />\n          T&C: {{ isTermsAccepted(selectedBalanceBooking) ? 'accepted' : 'not accepted' }}<br />\n          Booking status: {{ getStatusLabel(selectedBalanceBooking) }}<br />\n          {{ t('remainingToCollect') }}: <strong>€{{ getBalanceAmount(selectedBalanceBooking) }}</strong>\n        </p>\n\n        <label>\n          {{ t('paymentMethod') }}\n          <select [(ngModel)]=\"balancePaymentMethod\">\n            <option [value]=\"'sumup'\">{{ t('auto.home.bookings.bookings.component.sumup_card') }}</option>\n            <option [value]=\"'cash'\">{{ t('cash') }}</option>\n            <option [value]=\"'mixed'\">{{ t('mixed') }}</option>\n          </select>\n        </label>\n\n        <label>\n          {{ t('notes') }}\n          <textarea rows=\"3\" [(ngModel)]=\"balancePaymentNotes\" [placeholder]=\"t('optionalNote')\"></textarea>\n        </label>\n\n        <div class=\"modal-actions\">\n          <button class=\"btn btn-primary\" type=\"button\" [disabled]=\"savingBalancePayment\" (click)=\"recordBalancePayment()\">\n            {{ savingBalancePayment ? t('saving') : t('confirm90Payment') }}\n          </button>\n          <button class=\"btn btn-secondary\" type=\"button\" (click)=\"closeBalancePayment()\">{{ t('cancel') }}</button>\n        </div>\n\n        <p class=\"error-message\" *ngIf=\"balancePaymentError\">{{ balancePaymentError }}</p>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"status-modal-backdrop\" *ngIf=\"selectedStatusBooking\" (click)=\"closeStatusModal()\">\n    <section class=\"status-modal\" (click)=\"$event.stopPropagation()\">\n      <button class=\"modal-close\" type=\"button\" (click)=\"closeStatusModal()\">×</button>\n      <span class=\"eyebrow\">{{ t('bookingStatus') }}</span>\n      <h2>{{ getStatusLabel(selectedStatusBooking) }}</h2>\n      <p>{{ getStatusSummaryText(selectedStatusBooking) }}</p>\n\n      <div class=\"status-timeline\">\n        <div class=\"status-step\" [ngClass]=\"getStatusStepClass(isDepositPaid(selectedStatusBooking))\">\n          <strong>{{ t('deposit10') }}</strong>\n          <span>{{ getCompletedLabel(isDepositPaid(selectedStatusBooking)) }}</span>\n        </div>\n        <div class=\"status-step\" [ngClass]=\"getStatusStepClass(isTermsAccepted(selectedStatusBooking))\">\n          <strong>{{ t('tc') }}</strong>\n          <span>{{ isTermsAccepted(selectedStatusBooking) ? t('accepted') : t('notAccepted') }}</span>\n        </div>\n        <div class=\"status-step\" [ngClass]=\"getStatusStepClass(isWarrantySecured(selectedStatusBooking))\">\n          <strong>{{ t('warrantyMode') }}</strong>\n          <span>{{ getWarrantyModeLabel(selectedStatusBooking) }} · {{ getWarrantyCardLabel(selectedStatusBooking) }}</span>\n        </div>\n        <div class=\"status-step\" [ngClass]=\"getStatusStepClass(isBalancePaid(selectedStatusBooking))\">\n          <strong>{{ t('remaining90') }}</strong>\n          <span>{{ getCompletedLabel(isBalancePaid(selectedStatusBooking)) }}</span>\n        </div>\n        <div class=\"status-step\" [ngClass]=\"getStatusStepClass(getDamageStatusLabel(selectedStatusBooking).includes('recorded'))\">\n          <strong>{{ t('damage') }}</strong>\n          <span>{{ getDamageStatusLabel(selectedStatusBooking) }}</span>\n        </div>\n      </div>\n\n      <div class=\"modal-actions\">\n        <button class=\"btn btn-secondary\" type=\"button\" (click)=\"closeStatusModal()\">{{ t('close') }}</button>\n        <button class=\"btn btn-primary\" type=\"button\" (click)=\"openDetail(selectedStatusBooking)\">{{ t('openBooking') }}</button>\n      </div>\n    </section>\n  </div>\n\n</section>\n";

