module.exports = "<section class=\"account-page\">\n  <div class=\"container account-card\">\n    <span class=\"eyebrow\">{{ eyebrow }}</span>\n    <h1>{{ title }}</h1>\n    <p>{{ intro }}</p>\n\n    <ng-container *ngIf=\"section === 'payments'; else defaultAccountSection\">\n      <section class=\"standalone-payment-card\">\n        <div class=\"standalone-payment-copy\">\n          <span class=\"selector-kicker\">{{ paymentPageText('standaloneTitle') }}</span>\n          <p>{{ paymentPageText('standaloneHelp') }}</p>\n        </div>\n        <div class=\"standalone-payment-form\">\n          <label>\n            <span>{{ paymentPageText('standaloneAmount') }}</span>\n            <input type=\"number\" min=\"1\" step=\"0.01\" [(ngModel)]=\"standalonePaymentAmount\" [placeholder]=\"paymentPageText('standaloneAmountPlaceholder')\" />\n          </label>\n          <label class=\"standalone-comment\">\n            <span>{{ paymentPageText('standaloneComment') }}</span>\n            <textarea rows=\"3\" [(ngModel)]=\"standalonePaymentComment\" [placeholder]=\"paymentPageText('standaloneCommentPlaceholder')\"></textarea>\n          </label>\n          <p class=\"form-error\" *ngIf=\"standalonePaymentError\">{{ standalonePaymentError }}</p>\n          <button class=\"btn btn-primary\" type=\"button\" [disabled]=\"standalonePaymentLoading\" (click)=\"startStandalonePayment()\">\n            {{ standalonePaymentLoading ? paymentPageText('standaloneLoading') : paymentPageText('standaloneCta') }}\n          </button>\n        </div>\n      </section>\n\n      <section class=\"booking-selector-card\" *ngIf=\"!loading && paymentGroups.length > 0\">\n        <div class=\"booking-selector-copy\">\n          <span class=\"selector-kicker\">{{ paymentPageText('chooseBooking') }}</span>\n          <p>{{ paymentPageText('chooseHelp') }}</p>\n        </div>\n        <div class=\"booking-selector-control\">\n          <select [(ngModel)]=\"selectedBookingId\" aria-label=\"Booking\">\n            <option value=\"all\">{{ paymentPageText('allBookings') }}</option>\n            <option *ngFor=\"let group of paymentGroups\" [value]=\"group.bookingId\">\n              {{ group.customerName }} · {{ group.title }} · {{ group.date || '-' }} · {{ formatPaymentAmount(group.remainingAlegriaAmount + group.skipperAmount) }}\n            </option>\n          </select>\n          <div class=\"selected-booking-actions\" *ngIf=\"selectedPaymentGroup as selected\">\n            <div class=\"selected-due\">\n              <span>{{ paymentPageText('amountStillDue') }}</span>\n              <strong>{{ formatPaymentAmount(selected.remainingAlegriaAmount + (selected.skipperAmount || 0)) }}</strong>\n            </div>\n            <button class=\"btn btn-primary\" type=\"button\" (click)=\"openSelectedBooking(false)\">{{ paymentPageText('continuePayment') }}</button>\n            <button class=\"btn btn-secondary\" type=\"button\" (click)=\"openSelectedBooking(true)\">{{ paymentPageText('additionalPayment') }}</button>\n          </div>\n        </div>\n      </section>\n\n      <div class=\"payment-toolbar booking-payment-toolbar\">\n        <label>\n          <span>{{ paymentPageText('order') }}</span>\n          <select [(ngModel)]=\"paymentSortDirection\">\n            <option value=\"desc\">{{ paymentPageText('newestFirst') }}</option>\n            <option value=\"asc\">{{ paymentPageText('oldestFirst') }}</option>\n          </select>\n        </label>\n\n        <button class=\"btn btn-secondary\" type=\"button\" (click)=\"resetPaymentFilters()\">{{ paymentPageText('reset') }}</button>\n      </div>\n\n      <p *ngIf=\"loading\" class=\"muted\">{{ paymentPageText('loading') }}</p>\n\n      <div class=\"account-empty\" *ngIf=\"!loading && paymentGroups.length === 0\">\n        <p>{{ paymentPageText('empty') }}</p>\n        <a routerLink=\"/my-bookings\" class=\"btn btn-primary\">{{ paymentPageText('goToBookings') }}</a>\n      </div>\n\n      <div class=\"payment-summary\" *ngIf=\"!loading && paymentGroups.length > 0\">{{ paymentPageText('showing') }} <strong>{{ filteredPaymentGroups.length }}</strong> {{ paymentPageText(filteredPaymentGroups.length === 1 ? 'bookingSingular' : 'bookingPlural') }}.</div>\n\n      <div class=\"booking-payment-list\" *ngIf=\"!loading && filteredPaymentGroups.length > 0\">\n        <article class=\"booking-payment-card\" *ngFor=\"let group of filteredPaymentGroups\">\n          <div class=\"booking-payment-header\">\n            <div>\n              <div class=\"customer-line\"><span class=\"customer-avatar\">👤</span><div><h2>{{ group.customerName }}</h2><p>{{ group.title }} · {{ group.date || '-' }}</p></div></div><div class=\"booking-meta-line\"><span>{{ paymentPageText('passengers') }}: {{ group.passengers || '-' }}</span><span>{{ paymentPageText('reference') }}: {{ group.bookingId }}</span></div>\n            </div>\n            <span class=\"booking-status\" [ngClass]=\"group.statusClass\">{{ group.statusLabel }}</span>\n          </div>\n\n          <div class=\"booking-payment-grid\">\n            <div class=\"booking-payment-panel\">\n              <span class=\"panel-label\">{{ paymentPageText('financialSummary') }}</span>\n              <div class=\"amount-line\">\n                <span>{{ paymentPageText('totalOuting') }}</span>\n                <strong>{{ formatPaymentAmount(group.totalCustomerCost) }}</strong>\n              </div>\n              <div class=\"amount-line\">\n                <span>{{ paymentPageText('alegria') }}</span>\n                <strong>{{ formatPaymentAmount(group.alegriaAmount) }}</strong>\n              </div>\n              <div class=\"amount-line\">\n                <span>{{ paymentPageText('skipper') }}</span>\n                <strong>{{ formatPaymentAmount(group.skipperAmount) }}</strong>\n              </div>\n            </div>\n\n            <div class=\"booking-payment-panel highlight-panel\">\n              <span class=\"panel-label\">{{ paymentPageText('alegriaPayment') }}</span>\n              <div class=\"amount-line\">\n                <span>{{ paymentPageText('depositPaid') }}</span>\n                <strong>{{ formatPaymentAmount(group.depositPaidAmount) }}</strong>\n              </div>\n              <div class=\"amount-line total-line\">\n                <span>{{ paymentPageText('remaining') }}</span>\n                <strong>{{ formatPaymentAmount(group.remainingAlegriaAmount) }}</strong>\n              </div>\n              <button class=\"btn btn-primary compact-action\" type=\"button\" (click)=\"openBookingGroup(group)\">\n                {{ getPaymentActionLabel(group) }}\n              </button>\n            </div>\n\n            <div class=\"booking-payment-panel\">\n              <span class=\"panel-label\">{{ paymentPageText('skipper') }}</span>\n              <div class=\"amount-line total-line\">\n                <span>{{ paymentPageText('cashOnboard') }}</span>\n                <strong>{{ formatPaymentAmount(group.skipperAmount) }}</strong>\n              </div>\n              <small>{{ paymentPageText('skipperOnboardHelp') }}</small>\n            </div>\n\n            <div class=\"booking-payment-panel warranty-panel\">\n              <span class=\"panel-label\">{{ paymentPageText('warranty') }}</span>\n              <div class=\"amount-line\">\n                <span>{{ paymentPageText('standaloneAmount') }}</span>\n                <strong>{{ formatPaymentAmount(group.warrantyAmount) }}</strong>\n              </div>\n              <div class=\"amount-line\">\n                <span>{{ paymentPageText('mode') }}</span>\n                <strong>{{ group.warrantyMode }}</strong>\n              </div>\n              <div class=\"amount-line\">\n                <span>{{ paymentPageText('status') }}</span>\n                <strong>{{ group.warrantyStatus }}</strong>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"booking-payment-records\" *ngIf=\"group.visiblePayments.length > 0\">\n            <span>{{ paymentPageText('recordedPayments') }}</span>\n            <div class=\"mini-payment\" *ngFor=\"let payment of group.visiblePayments\">\n              <span>{{ payment.label }}</span>\n              <strong>{{ formatPaymentAmount(payment.amount) }}</strong>\n              <small>{{ payment.status }} · {{ payment.method }}</small>\n            </div>\n          </div>\n        </article>\n      </div>\n    </ng-container>\n\n    <ng-template #defaultAccountSection>\n      <div class=\"account-empty\">\n        <p>{{ emptyText }}</p>\n        <a routerLink=\"/contact\" class=\"btn btn-primary\">{{ content.nav.contact }}</a>\n      </div>\n    </ng-template>\n  </div>\n</section>\n";

