module.exports = "<section class=\"invoice-page\" *ngIf=\"!loading && booking\">\n  <div class=\"invoice-toolbar no-print\">\n    <a class=\"btn btn-secondary\" [routerLink]=\"['/admin/bookings', booking.bookingId]\">{{ 'auto.home.booking-invoice.booking-invoice.component.retour_r_servation' | siteText }}</a>\n    <button class=\"btn btn-secondary\" type=\"button\" (click)=\"addLine()\">{{ 'auto.home.booking-invoice.booking-invoice.component.ajouter_une_ligne' | siteText }}</button>\n    <button class=\"btn btn-primary\" type=\"button\" (click)=\"printPdf()\">{{ 'auto.home.booking-invoice.booking-invoice.component.imprimer_enregistrer_en_pdf' | siteText }}</button>\n  </div>\n\n  <article class=\"invoice-sheet\">\n    <header class=\"invoice-header\">\n      <div>\n        <h1>{{ 'auto.home.booking-invoice.booking-invoice.component.facture' | siteText }}</h1>\n        <p>{{ invoiceType === 'extras' ? 'Prestations additionnelles / Catering' : 'Prestations ALEGRIA' }}</p>\n      </div>\n      <div class=\"invoice-meta\">\n        <label>{{ 'auto.home.booking-invoice.booking-invoice.component.n_facture' | siteText }}<input [(ngModel)]=\"invoiceNumber\" /></label>\n        <label>{{ 'auto.home.booking-invoice.booking-invoice.component.date' | siteText }}<input type=\"date\" [(ngModel)]=\"invoiceDate\" /></label>\n      </div>\n    </header>\n\n    <section class=\"invoice-parties\">\n      <div>\n        <h2>{{ 'auto.home.booking-invoice.booking-invoice.component.metteur' | siteText }}</h2>\n        <label>{{ 'auto.home.booking-invoice.booking-invoice.component.nom' | siteText }}<input [(ngModel)]=\"sellerName\" /></label>\n        <label>{{ 'auto.home.booking-invoice.booking-invoice.component.d_tails' | siteText }}<textarea rows=\"3\" [(ngModel)]=\"sellerDetails\"></textarea></label>\n        <label>{{ 'auto.home.booking-invoice.booking-invoice.component.adresse' | siteText }}<textarea rows=\"2\" [(ngModel)]=\"sellerAddress\"></textarea></label>\n        <label>{{ 'auto.home.booking-invoice.booking-invoice.component.siret_tva' | siteText }}<input [(ngModel)]=\"sellerSiret\" /></label>\n      </div>\n\n      <div>\n        <h2>{{ 'auto.home.booking-invoice.booking-invoice.component.client' | siteText }}</h2>\n        <label>{{ 'auto.home.booking-invoice.booking-invoice.component.nom' | siteText }}<input [(ngModel)]=\"customerName\" /></label>\n        <label>{{ 'auto.home.booking-invoice.booking-invoice.component.email' | siteText }}<input [(ngModel)]=\"customerEmail\" /></label>\n        <label>{{ 'auto.home.booking-invoice.booking-invoice.component.adresse' | siteText }}<textarea rows=\"3\" [(ngModel)]=\"customerAddress\"></textarea></label>\n      </div>\n    </section>\n\n    <section class=\"booking-summary\">\n      <h2>{{ 'auto.home.booking-invoice.booking-invoice.component.sortie_concern_e' | siteText }}</h2>\n      <p>\n        <strong>{{ booking.outingType }}</strong><br />\n        Date : {{ booking.outingDate }}<br />\n        Horaires : {{ booking.departureTime || '-' }} - {{ booking.arrivalTime || '-' }}<br />\n        Passagers : {{ booking.passengers || '-' }}<br />\n        Référence réservation : {{ booking.bookingId }}\n      </p>\n    </section>\n\n    <section class=\"invoice-note\" *ngIf=\"invoiceType === 'booking'\">\n      <strong>{{ 'auto.home.booking-invoice.booking-invoice.component.note' | siteText }}</strong>{{ 'auto.home.booking-invoice.booking-invoice.component.les_frais_li_s_la_location_du_bateau_ont_t_encaiss' | siteText }}</section>\n\n    <table class=\"invoice-table\">\n      <thead>\n        <tr>\n          <th>{{ 'auto.home.booking-invoice.booking-invoice.component.description' | siteText }}</th>\n          <th>{{ 'auto.home.booking-invoice.booking-invoice.component.qt' | siteText }}</th>\n          <th>{{ 'auto.home.booking-invoice.booking-invoice.component.prix_unitaire' | siteText }}</th>\n          <th>{{ 'auto.home.booking-invoice.booking-invoice.component.total' | siteText }}</th>\n          <th class=\"no-print\"></th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr *ngFor=\"let line of lines; let i = index\">\n          <td><input [(ngModel)]=\"line.description\" /></td>\n          <td><input type=\"number\" min=\"0\" step=\"1\" [(ngModel)]=\"line.quantity\" /></td>\n          <td><input type=\"number\" min=\"0\" step=\"0.01\" [(ngModel)]=\"line.unitPrice\" /></td>\n          <td>€{{ getLineTotal(line) | number:'1.2-2' }}</td>\n          <td class=\"no-print\"><button type=\"button\" class=\"mini-btn\" (click)=\"removeLine(i)\">{{ 'auto.home.booking-invoice.booking-invoice.component.supprimer' | siteText }}</button></td>\n        </tr>\n      </tbody>\n      <tfoot>\n        <tr>\n          <td colspan=\"3\">{{ 'auto.home.booking-invoice.booking-invoice.component.total_ttc' | siteText }}</td>\n          <td>€{{ total | number:'1.2-2' }}</td>\n          <td class=\"no-print\"></td>\n        </tr>\n      </tfoot>\n    </table>\n\n    <section class=\"invoice-bottom\">\n      <label>{{ 'auto.home.booking-invoice.booking-invoice.component.conditions_de_paiement' | siteText }}<input [(ngModel)]=\"paymentTerms\" /></label>\n      <label>{{ 'auto.home.booking-invoice.booking-invoice.component.notes' | siteText }}<textarea rows=\"4\" [(ngModel)]=\"notes\"></textarea></label>\n    </section>\n  </article>\n</section>\n\n<p *ngIf=\"loading\" class=\"muted\">{{ 'auto.home.booking-invoice.booking-invoice.component.chargement_de_la_facture' | siteText }}</p>\n";

