"use strict";
module.exports = "<section class=\"admin-outing-detail-page\">\n  <div class=\"container\">\n    <button type=\"button\" class=\"back-link\" (click)=\"back()\">← {{ t('back') }}</button>\n\n    <div class=\"section-head\">\n      <span class=\"eyebrow\">{{ t('eyebrow') }}</span>\n      <h1>{{ t('title') }}</h1>\n      <p>{{ t('intro') }}</p>\n    </div>\n\n    <div class=\"notice error\" *ngIf=\"!isAdmin\">{{ t('adminOnly') }}</div>\n    <div class=\"notice error\" *ngIf=\"error\">{{ error }}</div>\n    <div class=\"notice success\" *ngIf=\"saved\">{{ t('saved') }}</div>\n\n    <ng-container *ngIf=\"isAdmin && outing\">\n      <div class=\"detail-card\">\n        <div class=\"status-row\">\n          <span class=\"status\" [class.closed]=\"outing.status === 'closed'\">\n            {{ outing.status === 'closed' ? t('closed') : t('open') }}\n          </span>\n        </div>\n\n        \n        <div class=\"outing-tabs\">\n          <button type=\"button\" class=\"outing-tab\" [class.active]=\"activeTab === 'details'\" (click)=\"activeTab = 'details'\">{{ 'auto.home.admin-outing-detail.admin-outing-detail.component.outing_details' | siteText }}</button>\n          <button type=\"button\" class=\"outing-tab\" [class.active]=\"activeTab === 'departure'\" (click)=\"activeTab = 'departure'\">{{ 'auto.home.admin-outing-detail.admin-outing-detail.component.departure' | siteText }}</button>\n          <button type=\"button\" class=\"outing-tab\" [class.active]=\"activeTab === 'anchoring'\" (click)=\"activeTab = 'anchoring'\">{{ 'auto.home.admin-outing-detail.admin-outing-detail.component.anchoring' | siteText }}</button>\n          <button type=\"button\" class=\"outing-tab\" [class.active]=\"activeTab === 'return'\" (click)=\"activeTab = 'return'\">{{ 'auto.home.admin-outing-detail.admin-outing-detail.component.return' | siteText }}</button>\n        </div>\n\n        <div class=\"form-grid\" *ngIf=\"activeTab === 'details'\">\n          <label>\n            {{ t('outingType') }}\n            <select [(ngModel)]=\"outing.outingType\">\n              <option *ngFor=\"let type of (outingTypes[currentLanguage] || outingTypes.en || outingTypes.fr)\" [value]=\"type\">{{ type }}</option>\n            </select>\n          </label>\n\n          <label>\n            {{ t('passengers') }}\n            <input type=\"number\" min=\"1\" [(ngModel)]=\"outing.passengers\" />\n          </label>\n\n          <label>\n            {{ t('departureDate') }}\n            <input type=\"date\" [(ngModel)]=\"outing.departureDate\" />\n          </label>\n\n          <label>\n            {{ t('departureTime') }}\n            <input type=\"time\" [(ngModel)]=\"outing.departureTime\" />\n          </label>\n\n          <label>\n            {{ t('arrivalDate') }}\n            <input type=\"date\" [(ngModel)]=\"outing.arrivalDate\" />\n          </label>\n\n          <label>\n            {{ t('arrivalTime') }}\n            <input type=\"time\" [(ngModel)]=\"outing.arrivalTime\" />\n          </label>\n\n          <label>\n            {{ t('portEngine') }}\n            <input type=\"number\" min=\"0\" step=\"0.1\" [(ngModel)]=\"outing.portEngineHoursDeparture\" />\n          </label>\n\n          <label>\n            {{ t('starboardEngine') }}\n            <input type=\"number\" min=\"0\" step=\"0.1\" [(ngModel)]=\"outing.starboardEngineHoursDeparture\" />\n          </label>\n\n          <label>\n            {{ t('wind') }} ({{ t('knots') }})\n            <input type=\"number\" min=\"0\" step=\"1\" [(ngModel)]=\"outing.actualWindSpeed\" />\n          </label>\n\n          <label class=\"wide\">\n            {{ t('destination') }}\n            <input type=\"text\" [(ngModel)]=\"outing.destination\" />\n          </label>\n\n          <label class=\"wide\">\n            {{ t('comments') }}\n            <textarea rows=\"4\" [(ngModel)]=\"outing.comments\"></textarea>\n          </label>\n\n          <label class=\"wide\">\n            {{ t('closureComments') }}\n            <textarea rows=\"3\" [(ngModel)]=\"outing.closureComments\"></textarea>\n          </label>\n        </div>\n\n        <div class=\"actions\">\n          <button type=\"button\" class=\"btn btn-primary\" [disabled]=\"saving\" (click)=\"saveDetails()\">\n            {{ saving ? t('saving') : t('save') }}\n          </button>\n          <button type=\"button\" class=\"btn btn-secondary\" *ngIf=\"outing.status !== 'closed'\" [disabled]=\"saving\" (click)=\"closeOuting()\">\n            {{ t('close') }}\n          </button>\n        </div>\n      </div>\n\n      <div class=\"checklist-card\">\n        <div class=\"checklist-head\">\n          <h2>{{ t('departureChecklist') }}</h2>\n          <span [class.complete]=\"departureComplete\">{{ countDoneDepartureItems() }} / {{ countDepartureItems() }}</span>\n        </div>\n\n        <div class=\"checklist-group\" *ngFor=\"let group of departureChecklistGroups\">\n          <div class=\"checklist-subhead\">\n            <h3>{{ group.title[currentLanguage] || group.title.fr }}</h3>\n            <span [class.complete]=\"countDoneGroup(group) === group.items.length\">{{ countDoneGroup(group) }} / {{ group.items.length }}</span>\n          </div>\n          <div class=\"checklist-grid\">\n            <label class=\"check-item\" *ngFor=\"let item of group.items\" [class.done]=\"item.done\">\n              <input type=\"checkbox\" [checked]=\"item.done\" (change)=\"toggleChecklist(item)\" />\n              <span class=\"fake-radio\"></span>\n              <span>\n                {{ item.label[currentLanguage] || item.label.fr }}\n                <small class=\"check-meta\" *ngIf=\"item.doneAt\">{{ formatChecklistMeta(item) }}</small>\n              </span>\n            </label>\n          </div>\n        </div>\n      </div>\n\n\n      <div class=\"checklist-card\">\n        <div class=\"checklist-head\">\n          <h2>{{ t('anchorages') }}</h2>\n          <span>{{ currentAnchorages.length }}</span>\n        </div>\n\n        <div class=\"form-grid\">\n          <label class=\"wide\">\n            {{ t('anchorageLocation') }}\n            <input type=\"text\" [(ngModel)]=\"anchorageForm.location\" [placeholder]=\"'auto.home.admin-outing-detail.admin-outing-detail.component.l_rins_baie_des_milliardaires_cap_d_antibes' | siteText\" />\n          </label>\n          <label class=\"wide\">\n            {{ t('comments') }}\n            <textarea rows=\"2\" [(ngModel)]=\"anchorageForm.comments\"></textarea>\n          </label>\n        </div>\n\n        <div class=\"actions\">\n          <button type=\"button\" class=\"btn btn-secondary\" (click)=\"addOrUpdateAnchorage()\">\n            {{ editingAnchorageId ? t('updateAnchorage') : t('dropAnchor') }}\n          </button>\n          <button type=\"button\" class=\"btn btn-secondary\" *ngIf=\"editingAnchorageId\" (click)=\"cancelAnchorageEdit()\">\n            {{ t('cancel') }}\n          </button>\n        </div>\n\n        <p class=\"empty\" *ngIf=\"currentAnchorages.length === 0\">—</p>\n\n        <div class=\"checklist-group\" *ngFor=\"let anchorage of currentAnchorages\">\n          <div class=\"checklist-subhead\">\n            <h3>{{ anchorage.location }}</h3>\n            <span [class.complete]=\"anchorage.status === 'closed'\">\n              {{ anchorage.status === 'closed' ? t('anchorageClosed') : t('anchorageOpen') }}\n            </span>\n          </div>\n          <p *ngIf=\"anchorage.arrivalTime || anchorage.departureTime\">{{ anchorage.arrivalTime || '—' }} → {{ anchorage.departureTime || '—' }}</p>\n          <p *ngIf=\"anchorage.comments\">{{ anchorage.comments }}</p>\n          <div class=\"actions\">\n            <button type=\"button\" class=\"btn btn-secondary\" *ngIf=\"anchorage.status !== 'closed'\" (click)=\"closeAnchorage(anchorage)\">{{ t('liftAnchor') }}</button>\n            <button type=\"button\" class=\"btn btn-secondary\" (click)=\"editAnchorage(anchorage)\">{{ t('edit') }}</button>\n            <button type=\"button\" class=\"btn btn-secondary\" (click)=\"removeAnchorage(anchorage)\">{{ t('delete') }}</button>\n          </div>\n\n          <div class=\"checklist-group\" *ngFor=\"let group of anchorage.arrivalChecklistGroups\">\n            <div class=\"checklist-subhead\">\n              <h3>{{ t('anchorageArrival') }}</h3>\n              <span [class.complete]=\"countDoneGroup(group) === group.items.length\">{{ countDoneGroup(group) }} / {{ group.items.length }}</span>\n            </div>\n            <div class=\"checklist-grid\">\n              <label class=\"check-item\" *ngFor=\"let item of group.items\" [class.done]=\"item.done\">\n                <input type=\"checkbox\" [checked]=\"item.done\" (change)=\"toggleChecklist(item)\" />\n                <span class=\"fake-radio\"></span>\n                <span>{{ item.label[currentLanguage] || item.label.fr }}<small class=\"check-meta\" *ngIf=\"item.doneAt\">{{ formatChecklistMeta(item) }}</small></span>\n              </label>\n            </div>\n          </div>\n\n          <div class=\"checklist-group\" *ngFor=\"let group of anchorage.departureChecklistGroups\">\n            <div class=\"checklist-subhead\">\n              <h3>{{ t('anchorageDeparture') }}</h3>\n              <span [class.complete]=\"countDoneGroup(group) === group.items.length\">{{ countDoneGroup(group) }} / {{ group.items.length }}</span>\n            </div>\n            <div class=\"checklist-grid\">\n              <label class=\"check-item\" *ngFor=\"let item of group.items\" [class.done]=\"item.done\">\n                <input type=\"checkbox\" [checked]=\"item.done\" (change)=\"toggleChecklist(item)\" />\n                <span class=\"fake-radio\"></span>\n                <span>{{ item.label[currentLanguage] || item.label.fr }}<small class=\"check-meta\" *ngIf=\"item.doneAt\">{{ formatChecklistMeta(item) }}</small></span>\n              </label>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"checklist-card\">\n        <div class=\"checklist-head\">\n          <h2>{{ t('arrivalChecklist') }}</h2>\n          <span [class.complete]=\"arrivalComplete\">{{ countDoneArrivalItems() }} / {{ countArrivalItems() }}</span>\n        </div>\n\n        <div class=\"checklist-group\" *ngFor=\"let group of arrivalChecklistGroups\">\n          <div class=\"checklist-subhead\">\n            <h3>{{ group.title[currentLanguage] || group.title.fr }}</h3>\n            <span [class.complete]=\"countDoneGroup(group) === group.items.length\">{{ countDoneGroup(group) }} / {{ group.items.length }}</span>\n          </div>\n          <div class=\"checklist-grid\">\n            <label class=\"check-item\" *ngFor=\"let item of group.items\" [class.done]=\"item.done\">\n              <input type=\"checkbox\" [checked]=\"item.done\" (change)=\"toggleChecklist(item)\" />\n              <span class=\"fake-radio\"></span>\n              <span>\n                {{ item.label[currentLanguage] || item.label.fr }}\n                <small class=\"check-meta\" *ngIf=\"item.doneAt\">{{ formatChecklistMeta(item) }}</small>\n              </span>\n            </label>\n          </div>\n        </div>\n      </div>\n    </ng-container>\n  </div>\n</section>\n";

